using System;
using Ashfall.Core;
using Ashfall.Modules.WeaponHandling;
class PreparedTests
{
 static int checks,commands; static long tick,seq;
 static void A(bool v,string s){checks++;if(!v)throw new Exception(s);}
 sealed class Host:IAuthorityGate,IWeaponLifetimeAuthority {public bool Allow=true;public RuleResult Validate(CommandContext c){return Allow?RuleResult.Accept():RuleResult.Reject("denied");}public RuleResult AuthorizeNew(CommandContext c,string id,WeaponMechanism m,int n){return Validate(c);}public RuleResult AuthorizeRestore(CommandContext c,string id,string actor,long e){return Validate(c);}}
 sealed class Ammo:IRevisionedAmmoReserve{int count=20;long version;public int Available{get{return count;}}public long Revision{get{return version;}}public int Take(int n){int k=Math.Min(n,count);count-=k;version++;return k;}public int Refund(int n){count+=n;version++;return n;}}
 static CommandContext C(string actor="a",long epoch=1){return new CommandContext("s",actor,"p"+(++commands),++tick,epoch,true);}
 static HandlingInput I(bool trigger=false){return new HandlingInput{Sequence=++seq,Enabled=true,PrimaryTracked=true,SupportTracked=true,Desktop=true,Trigger=trigger,DeltaSeconds=.05f};}
 static WeaponHandling New(WeaponLifetimes l,Ammo ammo,WeaponMechanism m){WeaponHandling w;A(l.CreateNew(C(),"gun",m,3,ammo,new Host(),out w).Accepted,"create actual ledger");return w;}
 static void Main(){
  var host=new Host();var ammo=new Ammo();var ledger=new WeaponLifetimes("s",host);var w=New(ledger,ammo,WeaponMechanism.PrecisionRifle);IPreparedWeaponTransfer p;
  A(ledger.PrepareTransfer(C(),"gun","b",2,out p).Accepted,"prepare");A(p.Result==null&&w.Snapshot.Loaded==3,"prepare opaque and no ammo change");A(w.Apply(C(),HandlingAction.Fire,I(true)).Accepted,"active handler remains playable");A(!p.Validate().Accepted,"mechanical mutation stales prepare");p.Abort();p.Abort();A(w.Snapshot.Loaded==2,"abort twice preserves shot");
  A(ledger.PrepareTransfer(C(),"gun","b",2,out p).Accepted,"prepare spent chamber");host.Allow=false;A(!p.Validate().Accepted,"denied final restore");p.CommitValidated();A(p.Result==null,"denied cannot publish");host.Allow=true;A(p.Validate().Accepted,"permission recovered");p.Abort();A(!p.Validate().Accepted,"abort final");
  A(ledger.PrepareTransfer(C(),"gun","b",2,out p).Accepted,"reserve ABA prepare");ammo.Take(1);ammo.Refund(1);A(!p.Validate().Accepted,"equal count reserve ABA rejected");p.Abort();
  IPreparedWeaponTransfer race;A(ledger.PrepareTransfer(C(),"gun","b",2,out p).Accepted,"race first");A(ledger.PrepareTransfer(C(),"gun","c",2,out race).Accepted,"race second");A(p.Validate().Accepted&&race.Validate().Accepted,"race candidates");p.CommitValidated();race.CommitValidated();A(p.Result!=null&&race.Result==null,"only exact active wins");p.Abort();p.Abort();p.CommitValidated();A(p.Result.ActorId=="b"&&p.Result.Epoch==2,"postsuccess abort preserves owner");A(p.Result.Snapshot.Loaded==2&&p.Result.Snapshot.SpentChamber&&!p.Result.Snapshot.Chambered&&ammo.Available==20,"exact rounds chamber reserve");A(!w.Apply(C(),HandlingAction.Sample,I()).Accepted,"retired old handler");A(!p.Result.Handler.Apply(C(),HandlingAction.Sample,I()).Accepted,"old epoch rejects");A(!ledger.PrepareTransfer(C(),"gun","c",2,out race).Accepted,"old owner rejects");A(ledger.PrepareTransfer(C("b",2),"gun","authenticated-new-actor",3,out race).Accepted,"authenticated remap approved by real port");A(race.Validate().Accepted,"remap validate");race.CommitValidated();A(race.Result.ActorId=="authenticated-new-actor"&&race.Result.Snapshot.Loaded==2,"remap conserves");
  host=new Host();ammo=new Ammo();ledger=new WeaponLifetimes("s",host);w=New(ledger,ammo,WeaponMechanism.ServiceRifle);var input=I();input.Grip=true;input.ForegripDistance=.01f;A(w.Apply(C(),HandlingAction.Sample,input).Accepted&&w.Snapshot.ClaimsSupport,"actual support engaged");IPreparedWeaponSuspension suspend;A(w.PrepareSuspension(out suspend).Accepted&&w.Snapshot.ClaimsSupport,"prepare preserves contact");A(suspend.Validate().Accepted,"suspension validate");suspend.CommitValidated();suspend.Abort();A(!w.Snapshot.ClaimsSupport&&w.Snapshot.Loaded==3&&w.Snapshot.TriggerReleaseRequired,"commit disarms without ammo change");
  A(w.PrepareSuspension(out suspend).Accepted,"second suspension");w.Apply(C(),HandlingAction.Sample,I());A(!suspend.Validate().Accepted,"stale suspension");suspend.Abort();suspend.Abort();
  foreach(bool left in new[]{false,true})foreach(int mode in new[]{0,1,2,3,4,5,6})Flick(left,mode);
  Console.WriteLine("PASS "+checks+" prepared lifetime/suspension/source flick checks; no world/inventory migration or durable claim");
 }
 static void Flick(bool left,int mode){var host=new Host();var ammo=new Ammo();var l=new WeaponLifetimes("s",host);var w=New(l,ammo,WeaponMechanism.MagnumRevolver);A(w.Apply(C(),HandlingAction.Eject,I()).Accepted,"open");w.Apply(C(),HandlingAction.Sample,I());A(w.Apply(C(),HandlingAction.ReloadStep,I()).Accepted,"load");A(w.Snapshot.Loaded==7&&ammo.Available==16,"topup exact");
  var i=I();i.Desktop=false;i.LeftHanded=left;i.SupportTracked=false;i.SupportReserved=true;i.HasPrimaryPose=true;i.PrimaryForward=new Float3(0,0,1);i.PrimaryUp=new Float3(0,1,0);A(w.Apply(C(),HandlingAction.Sample,i).Accepted,"neutral primary with absent offhand");
  if(mode==0)i.PrimaryPoint=new Float3(.06f,0,0);if(mode==1)i.PrimaryForward=new Float3(.35f,0,.93675f);if(mode==2)i.PrimaryUp=new Float3(.35f,.93675f,0);if(mode==3)i.PrimaryPoint=new Float3(-.06f,0,0);if(mode==4){i.Trigger=true;i.PrimaryPoint=new Float3(.06f,0,0);}if(mode==5){i.PrimaryTracked=false;i.PrimaryPoint=new Float3(.06f,0,0);}if(mode==6){IPreparedWeaponSuspension p;w.PrepareSuspension(out p);p.Validate();p.CommitValidated();i.PrimaryPoint=new Float3(.06f,0,0);}
  i.Sequence=++seq;w.Apply(C(),HandlingAction.Sample,i);A((w.Snapshot.Phase==ReloadPhase.Ready)==(mode<3),"source RIGHT translation/pitch/roll both dominance plus interruption");A(w.Snapshot.Loaded==7&&ammo.Available==16,"flick conserves rounds");
 }
}
